import { test } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import type { AddressInfo } from "node:net";
import { LocalLlmClient } from "../src/client.js";

type Handler = (req: http.IncomingMessage, res: http.ServerResponse, body: string) => void;

async function withServer<T>(handler: Handler, fn: (base: string) => Promise<T>): Promise<T> {
  const server = http.createServer((req, res) => {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => handler(req, res, body));
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  try {
    return await fn(`http://127.0.0.1:${(server.address() as AddressInfo).port}`);
  } finally {
    server.closeAllConnections?.();
    server.close();
  }
}

const json = (res: http.ServerResponse, body: unknown) => {
  res.setHeader("Content-Type", "application/json");
  res.end(JSON.stringify(body));
};

test("setModel switches the model in place and suppresses the routing hint without a positive handshake", async () => {
  const seen: { model?: string; taskClass?: string | string[] }[] = [];
  await withServer(
    (req, res, body) => {
      seen.push({ model: JSON.parse(body).model, taskClass: req.headers["x-task-class"] });
      json(res, { choices: [{ message: { role: "assistant", content: "ok" }, finish_reason: "stop" }] });
    },
    async (base) => {
      const c = new LocalLlmClient({ model: "a", endpoint: base, apiKey: "k", taskClass: "review" } as any);
      await c.chatCompletion([{ role: "user", content: "x" }], []);
      c.setModel("b");
      await c.chatCompletion([{ role: "user", content: "x" }], []);
    },
  );
  assert.deepEqual(seen, [
    { model: "a", taskClass: undefined },
    { model: "b", taskClass: undefined },
  ]);
});

test("a tool call cut off by the token limit is rejected, not executed", async () => {
  await withServer(
    (_req, res) =>
      json(res, {
        choices: [
          {
            finish_reason: "length",
            message: { role: "assistant", content: "", tool_calls: [{ id: "1", type: "function", function: { name: "write_file", arguments: '{"path":"a.py","content":"def f(' } }] },
          },
        ],
      }),
    async (base) => {
  const invalidOperatorBinding = Boolean(operatorKey && configuredCredentialOrigin && !operatorOrigin);
  const projectCredential = projectSetting("LOCAL_LLM_API_KEY");
  const invalidFallback = projectCredential !== undefined ? (projectCredential === operatorKey ? undefined : projectCredential) : (projectApiKey === operatorKey ? undefined : projectApiKey);
  const envCredential = options.apiKey || provider ? undefined : environmentCredential(options.endpoint || DEFAULT_ENDPOINT);
  const apiKey = options.apiKey || (provider ? providerKey(provider) : provisionalKey || (invalidOperatorBinding ? invalidFallback : operatorKey || projectApiKey || envCredential?.apiKey)) || "local";
  const credentialOrigin = apiKey === "local" ? undefined : options.apiKey || provider || provisionalKey ? credentialOriginOf(endpoint) : (invalidOperatorBinding ? credentialOriginOf(endpoint) : (operatorKey ? operatorOrigin : (projectApiKey ? credentialOriginOf(endpoint) : envCredential?.origin)));
  const workspace = options.workspace ? path.resolve(options.workspace) : process.cwd();
  const maxSteps = options.maxSteps ? parseInt(options.maxSteps, 10) : 30;
  const continuation = continuationBudget(options);
  const temperature = options.temperature ? parseFloat(options.temperature) : 0.2;
  const shell = options.shell || operatorSetting("LOCAL_HARNESS_SHELL") || process.env.LOCAL_HARNESS_SHELL || "bash";
  const dryRun = Boolean(options.dryRun);
  const readOnly = Boolean(options.readOnly);
  const yes = Boolean(options.yes);
  const approve = Boolean(options.approve);
  const modeOption = options.mode ? String(options.mode).toLowerCase() : undefined;
  const envMode = (operatorSetting("NEXUS_APPROVAL_MODE") || process.env.NEXUS_APPROVAL_MODE)?.trim().toLowerCase();

